CREATE TRIGGER event_offset_in_recording BEFORE INSERT ON events FOR EACH ROW EXECUTE FUNCTION partrace_event_offset_in_recording();

CREATE OR REPLACE FUNCTION public.partrace_event_offset_in_recording()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.end_offset_ms > (SELECT duration_ms FROM recordings WHERE recording_id = NEW.recording_id) THEN
        RAISE EXCEPTION 'event offsets exceed recording duration' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$
;

