BEGIN
    IF NEW.offset_ms > (
        SELECT r.duration_ms FROM recordings r JOIN events e ON e.recording_id = r.recording_id
        WHERE e.event_id = NEW.event_id
    ) THEN
        RAISE EXCEPTION 'evidence offset exceeds recording duration' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$
;

