CREATE TRIGGER assistant_message_completed_run BEFORE INSERT ON messages FOR EACH ROW WHEN (new.role = 'assistant'::text) EXECUTE FUNCTION partrace_assistant_completed_run();

CREATE OR REPLACE FUNCTION public.partrace_assistant_completed_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM runs
        WHERE run_id = NEW.run_id AND conversation_id = NEW.conversation_id AND status = 'completed'
    ) THEN
        RAISE EXCEPTION 'assistant reply requires a completed run in the same conversation' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$
;

